#!/usr/bin/env python3
from pathlib import Path
import base64,gzip,re,sys
root=Path(sys.argv[1] if len(sys.argv)>1 else 'pkg')
files={
'api/volunteer_menu_v1435.php':'',
'api/scale-day-pdf-v1435.php':'',
}
for rel,b64 in files.items():
    p=root/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(gzip.decompress(base64.b64decode(b64)))
p=root/'api/pending_router_v1311.php'
s=p.read_text()
old="require_once __DIR__.'/whatsapp_transport_v1424.php'; require_once __DIR__.'/volunteer_menu_v1434.php';"
new="require_once __DIR__.'/whatsapp_transport_v1424.php'; require_once __DIR__.'/volunteer_menu_v1435.php';"
if old not in s and new not in s: raise SystemExit('include do menu nao encontrado')
s=s.replace(old,new,1)
old="function v1311p_select_option(array $session,array $profiles,string $sender,string $text): bool { $options=json_decode((string)($session['options_json']??''),true);"
new="function v1311p_select_option(array $session,array $profiles,string $sender,string $text): bool { if(v1311p_is_menu_word($text)) { return function_exists('v1435_show_home')?v1435_show_home($sender,$profiles,$session):false; } $options=json_decode((string)($session['options_json']??''),true);"
if old in s:s=s.replace(old,new,1)
elif new not in s:raise SystemExit('v1311p_select_option nao localizado')
s=s.replace("if(v1311p_is_menu_word($text)){v1311p_delete_session($session);$fresh=v1311p_collect_options($profiles);return$fresh?v1311p_show_menu($sender,$profiles,$fresh,null):false;}", "if(v1311p_is_menu_word($text)){return function_exists('v1435_show_home')?v1435_show_home($sender,$profiles,$session):false;}")
s=s.replace("if(function_exists('v1434_is_menu_state')&&v1434_is_menu_state($state))return v1434_handle_menu_session($session,$profiles,$sender,$text);", "if(function_exists('v1435_is_menu_state')&&v1435_is_menu_state($state))return v1435_handle_menu_session($session,$profiles,$sender,$text);")
s=s.replace("v1311p_send($sender,(string)($profiles[0]['igreja_id']??''),\"✅ Você não possui mais pendências para responder.\",'no_pending_after_stale_selection');return true;", "return function_exists('v1435_show_home')?v1435_show_home($sender,$profiles,null):v1311p_send($sender,(string)($profiles[0]['igreja_id']??''),\"✅ Você não possui mais pendências para responder.\",'no_pending_after_stale_selection');")
oldblock="$options=v1311p_collect_options($profiles); if(!$options){ if(v1311p_is_menu_word($text)){ if(!v1311p_mark_event($msg))return true; return function_exists('v1434_show_home')?v1434_show_home($sender,$profiles,null):false; } return false; } if(v1311p_is_menu_word($text)||count($options)>1){ if(!v1311p_mark_event($msg))return true; return v1311p_show_menu($sender,$profiles,$options,null); }"
newblock="if(v1311p_is_menu_word($text)){ if(!v1311p_mark_event($msg))return true; return function_exists('v1435_show_home')?v1435_show_home($sender,$profiles,null):false; } $options=v1311p_collect_options($profiles); if(!$options){ return false; } if(count($options)>1){ if(!v1311p_mark_event($msg))return true; return v1311p_show_menu($sender,$profiles,$options,null); }"
if oldblock in s:s=s.replace(oldblock,newblock,1)
elif newblock not in s:raise SystemExit('bloco de roteamento MENU nao localizado')
p.write_text(s)
(root/'VERSION').write_text('1.4.35\n')
sp=root/'sistema.html'
if sp.exists():
    ss=sp.read_text();ss=re.sub(r'(/assets/index-C6Ng0a8i\.js\?v=)[^"<]+',r'\g<1>1.4.35',ss);sp.write_text(ss)
sw=root/'sw.js'
if sw.exists():sw.write_text(sw.read_text()+'\n/* volunteer-whatsapp-menu-v1.4.35 */\n')
(root/'ATUALIZACAO-v1.4.35.md').write_text('# Escala de Propósito v1.4.35\n\n- Reorganiza o MENU do voluntário no WhatsApp em 4 opções fixas: Pendências, dias escalados, PDF da escala completa e dias indisponíveis.\n- A opção Pendências mostra escalas/quizzes que ainda precisam de resposta.\n- A opção Dias escalados mostra as escalas confirmadas dos próximos 30 dias.\n- A opção PDF permite escolher o culto e envia a escala completa do dia.\n- O PDF do WhatsApp passa a usar o mesmo modelo visual do painel: cabeçalho, tabela Departamento/Função/Voluntário/Situação e Repertório.\n- A opção Indisponibilidade aceita uma ou várias datas DD/MM/AAAA e grava na mesma tabela usada pela tela Disponibilidade do aplicativo.\n- Mantém intacto o núcleo de confirmação/recusa 1 e 2 e a resiliência da Evolution da v1.4.33.\n')
